+// validateOCIRepository mirrors the supported schemes of the OCI store without
+// importing it (the store itself depends on configuration).
+func validateOCIRepository(repository string) error {
+	scheme, target, explicit := strings.Cut(repository, "://")
+	if !explicit {
+		target = scheme
+		scheme = "https"
+	}
+	if !strings.Contains(target, "/") {
+		target = "local/" + target
+		scheme = "flipt"
+	}
+	ref, err := registry.ParseReference(target)
+	if err != nil {
+		return err
+	}
+	switch scheme {
+	case "http", "https":
+	case "flipt":
+		if ref.Registry != "local" {
+			return fmt.Errorf("unexpected local reference: %q", ref)
+		}
+	default:
+		return fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", scheme)
+	}
+	return nil
+}
